dtsPropsFor.TripCard:
/** A row from the trips table. Dates are YYYY-MM-DD; end_date null = the trip is ongoing (shows 'Present' and an active dot). */
trip: { id: number; city: string; country: string; country_code: string; latitude: number | null; longitude: number | null; start_date: string; end_date: string | null; days: number; sync_id: string | null; updated_at: string | null; deleted: number };
daysOverride?: number;
hasOverlap?: boolean;
/** Compact mode: no timeline dot, no country label (used inside country groups) */
compact?: boolean;
onDelete?: (id: number) => void;
onEdit?: (trip: TripCardProps['trip']) => void;

dtsPropsFor.GuideCard:
/** A destination guide. image is a photo URL; legs drive the 'N stops · N days' line (days = max endOffset - min startOffset + 1). */
guide: { id: string; flag: string; countryCode: string; country: string; tagline: string; image: string; apps: { name: string; domain: string }[]; tips: string[]; legs: { city: string; country: string; countryCode: string; startOffset: number; endOffset: number; transport: 'flight' | 'train' | 'car' | 'bus' | 'ferry' | 'walk'; latitude: number; longitude: number }[] };
onPress: () => void;

dtsPropsFor.YearPicker:
/** Available years to choose from (newest first). */
years: number[];
/** Selected year, or null for 'All Time'. */
value: number | null;
onChange: (next: number | null) => void;
/** Hide the "All Time" pill when you only want concrete years (e.g. tax). */
includeAllTime?: boolean;

dtsPropsFor.PillRow:
/** One pill each. Exactly one is usually active (filled black, white text). icon is an Ionicons name. */
options: { key: string; label: string; icon?: string; leading?: React.ReactNode; active?: boolean; onPress: () => void; onLongPress?: () => void }[];
/** Tabular digits, for year pills. */
tabular?: boolean;

dtsPropsFor.TimelineBubbles:
size?: number;
variant?: 'burstWobble' | 'none' | 'pop' | 'burst' | 'wobble';
/** Three icons to render: [left, center, right]. Center is the prominent / colored one. name is an Ionicons name. */
icons?: [{ name: string; color?: string }, { name: string; color?: string }, { name: string; color?: string }];

dtsPropsFor.Ionicons:
/** Ionicons glyph name, e.g. 'airplane', 'bed-outline', 'calendar-outline'. Outline variants end in -outline. */
name: string;
size?: number;
color?: string;
style?: React.CSSProperties;

dtsPropsFor.Flag:
/** ISO-3166 alpha-2 country code (case-insensitive). */
code: string;
/** Display height in pt. Width follows the flag's aspect ratio. */
size?: number;
/** Adds a subtle rounded corner + hairline border so the flag sits nicely inside cards. Set `false` for a flat raw look (e.g. inside a circular bubble). */
rounded?: boolean;
style?: object;
